<div class="page-heading"><div><div class="eyebrow">Administrasi</div><h1>Akun petugas</h1><p>Buat akun internal sesuai peran dan nonaktifkan akun yang tidak digunakan.</p></div></div>
<div class="detail-grid"><div><section class="card detail-card"><h2>Daftar petugas</h2><div class="table-scroll"><table><thead><tr><th>Nama</th><th>Peran</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($staff as $person): ?><tr><td><strong><?= e($person->full_name) ?></strong><small><?= e($person->email) ?></small></td><td><?= e($person->role_name) ?></td><td><?= e($person->account_status === 'active' ? 'Aktif' : 'Nonaktif') ?></td><td><?php if ((int) $person->id !== (int) $current_user->id && $person->account_status === 'active'): ?><form method="post" action="<?= site_url('staff/deactivate/' . $person->id) ?>" onsubmit="return confirm('Nonaktifkan akun ini?')"><?= form_hidden($this->security->get_csrf_token_name(), $this->security->get_csrf_hash()) ?><button class="text-button" type="submit">Nonaktifkan</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section></div>
<aside><section class="card detail-card"><h2>Buat akun</h2><form method="post" action="<?= site_url('petugas/akun') ?>"><?= form_hidden($this->security->get_csrf_token_name(), $this->security->get_csrf_hash()) ?><label>Nama lengkap<input name="full_name" required minlength="3" maxlength="160"></label><label>Email<input type="email" name="email" required></label><label>Peran<select name="role_code" required><option value="verifier">Verifikator</option><option value="technician">Petugas teknis</option><option value="coordinator">Koordinator</option><option value="issuer">Pejabat penerbit</option></select></label><label>Kata sandi awal<input type="password" name="password" minlength="12" maxlength="72" required></label><button class="button primary full" type="submit">Buat akun petugas</button></form></section></aside></div>
